// src/serverless.ts
var app = createApp();
var GET = handle(app);
var POST = handle(app);
var PUT = handle(app);
var PATCH = handle(app);
var DELETE = handle(app);
var OPTIONS = handle(app);
var serverless_default = handle(app);
export {
  DELETE,
  GET,
  OPTIONS,
  PATCH,
  POST,
  PUT,
  serverless_default as default
};
